import React from 'react';
import SummaryCards from '../components/dashboard/SummaryCards';
import SurveyProgress from '../components/dashboard/SurveyProgress';
import RecentActivity from '../components/dashboard/RecentActivity';
import PropertyStats from '../components/dashboard/PropertyStats';

function Dashboard() {
  // Mock data for demonstration
  const mockStats = {
    totalProperties: 12,
    totalSurveys: 45,
    completedSurveys: 38,
    pendingSurveys: 7
  };

  const mockSurveyStatuses = {
    completed: 38,
    inProgress: 5,
    pending: 2
  };

  const mockUserActivity = [
    { id: 1, user: 'Admin User', action: 'Completed survey for Building A', time: '2 hours ago' },
    { id: 2, user: 'John Doe', action: 'Started new survey', time: '4 hours ago' },
    { id: 3, user: 'Jane Smith', action: 'Updated property details', time: '6 hours ago' }
  ];

  const mockPropertyStats = {
    totalArea: 25000,
    surveyedArea: 18000,
    completionRate: 72
  };

  const mockProperties = [
    { id: 1, name: 'Property A', status: 'completed' },
    { id: 2, name: 'Property B', status: 'in-progress' },
    { id: 3, name: 'Property C', status: 'pending' }
  ];

  const userRole = 'admin';

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-8">
          <h1 className="text-3xl font-bold text-gray-900">Dashboard</h1>
          <p className="text-gray-600 mt-2">Welcome to your Site Survey Tool</p>
        </div>

        {/* Summary Cards */}
        <div className="mb-8">
          <SummaryCards stats={mockStats} userRole={userRole} />
        </div>

        {/* Main Grid */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Survey Progress */}
          <div className="lg:col-span-2">
            <SurveyProgress surveyStatuses={mockSurveyStatuses} userRole={userRole} />
          </div>

          {/* Recent Activity */}
          <div>
            <RecentActivity userActivity={mockUserActivity} />
          </div>
        </div>

        {/* Property Stats */}
        <div className="mt-8">
          <PropertyStats 
            propertyStats={mockPropertyStats} 
            properties={mockProperties} 
            userRole={userRole} 
          />
        </div>
      </div>
    </div>
  );
}

export default Dashboard;
